# Mock calculate_stock_volatility for testing purposes
def calculate_stock_volatility(prices):
    # For testing, let's use stdev
    if len(prices) < 2:
        return 0.0
    mean = sum(prices) / len(prices)
    variance = sum((p - mean) ** 2 for p in prices) / (len(prices) - 1)
    return variance ** 0.5

def portfolio_risk_assessment(portfolio):
    risk = 0.0
    for stock, info in portfolio.items():
        prices = info['prices']
        alloc = info['allocation']
        volatility = calculate_stock_volatility(prices)
        risk += volatility * alloc
    return risk


