# For testing, we need to mock or define calculate_stock_volatility.
def calculate_stock_volatility(prices):
    # For simplicity, let's use standard deviation as a mock.
    # This is not a robust stddev, but sufficient for test illustration.
    if not prices:
        return 0.0
    mean = sum(prices) / len(prices)
    variance = sum((p - mean) ** 2 for p in prices) / len(prices)
    return variance ** 0.5

def portfolio_risk_assessment(portfolio):
    '''
    Takes a dict where keys are stock names and values have 'prices' list and 'allocation' float.
    For each stock, call calculate_stock_volatility(prices), multiply by allocation, sum all weighted volatilities.
    Returns: float representing total portfolio risk as weighted sum.
    '''
    total_risk = 0.0
    for stock, info in portfolio.items():
        volatility = calculate_stock_volatility(info['prices'])
        total_risk += volatility * info['allocation']
    return total_risk


